"use strict";
const assert=require("node:assert/strict"),fs=require("node:fs"),path=require("node:path"),{spawnSync}=require("node:child_process"),r=require("./fixtures/d3d_texture_copy_reference.json");
(async()=>{const{site_directory}=await import("../lib/site.mjs"),root=path.resolve(__dirname,"../.."),site=site_directory(root),generated=spawnSync(process.execPath,[root+"/tools/gen_d3d_texture_copy_reference.mjs"],{encoding:"utf8"});assert.equal(generated.status,0,generated.stderr);assert.equal(fs.readFileSync(site+"/glbridge/tests/native/d3d_texture_copy_reference.h","utf8"),generated.stdout);assert.equal(r.scenes.length,7);assert.equal(r.scenes.reduce((n,s)=>n+s.frames.length,0),42);for(const s of r.scenes){assert.equal(s.sourceSkip,2);assert.equal(s.copyLevels,Math.min(s.source.levels-s.sourceSkip,s.destination.levels));for(const f of s.frames){assert(f.mip<s.destination.levels);const color=f.mip>=s.copyLevels?r.sentinelARGB:r.paletteARGB[(f.mip+s.sourceSkip+(s.kind===1?f.face:s.kind===2?f.slice:0))%6];assert.equal(f.expectedARGB,color);}}assert(r.scenes.some(s=>s.source.depth>s.source.width));assert(r.scenes.some(s=>s.usage===1));assert.equal(r.sources.length,3);for(const source of r.sources){assert.match(source.blobSha1,/^[a-f0-9]{40}$/);assert.match(source.sha256,/^[a-f0-9]{64}$/);}assert.match(r.scope,/no original Microsoft HAL pixel claim/);console.log("PASS independent texture copy reference: seven scenes, 42 frames, matched mips, short chains, cube faces, volume/depth slices and lazy mirrors; three pinned Wine sources");})().catch(e=>{console.error(e);process.exitCode=1;});
